```javascript
const sortObjectByKeys = (obj) => {
  const entries = Object.entries(obj);
  entries.sort((a, b) => {
    const [keyA, valueA] = a;
    const [keyB, valueB] = b;
    return keyA.localeCompare(keyB);
  });
  return Object.fromEntries(entries);
};

