Here's a JavaScript function that takes a dot-notated string as input, searches for a specific key-value pair within an object, and returns an array of all options that match:

```js
function findOptionsByKey(object, keyPath, value) {
  let result = [];

  // Split the key path into an array of keys
  const keys = keyPath.split('.');

  // Traverse the object recursively and add options that match the value
  function traverseObject(obj) {
    for (let key in obj) {
      if (typeof obj[key] === 'object') {
        traverseObject(obj[key]);
      } else if (keys.length === keys.reduce((acc, curr) => acc && obj[curr], true)) {
        if (obj[keys[keys.length - 1]] === value) {
          result.push(obj);
        }
      }
    }
  }

  traverseObject(object);

  return result;
}

// Example usage
const data = {
  a: { b: { c: 'foo', d: ['bar', 'baz'] } },
  e: { f: [{ g: 'qux', h: 'quux' }], [g: 'quuz'] }
};
const options = findOptionsByKey(data, 'a.b.d', 'bar');
console.log(options); // Output: [{ "a": { "b": { "c": "foo", "d": [ "bar", "baz" ] } } }]
```

